using System;
using System.Collections.Generic;
using System.Threading.Tasks;

public record HttpRequest(string Method, string Path, object? Body);
public record HttpResponse(int StatusCode, object? Content);

public interface IEndpointFilter
{
    ValueTask<HttpResponse> InvokeAsync(HttpRequest request, Func<HttpRequest, ValueTask<HttpResponse>> next);
}

public class OrderValidationFilter : IEndpointFilter
{
    public async ValueTask<HttpResponse> InvokeAsync(HttpRequest request, Func<HttpRequest, ValueTask<HttpResponse>> next)
    {
        if (request.Body is null || (request.Body is string str && string.IsNullOrWhiteSpace(str)))
        {
            return new HttpResponse(400, "Validation Failed: Body cannot be empty");
        }

        return await next(request);
    }
}

public class Program
{
    public static async Task Main()
    {
        var filter = new OrderValidationFilter();

        Func<HttpRequest, ValueTask<HttpResponse>> endpointHandler = req =>
        {
            return ValueTask.FromResult(new HttpResponse(200, $"Order Created: {req.Body}"));
        };

        var invalidReq = new HttpRequest("POST", "/api/orders", null);
        var resp1 = await filter.InvokeAsync(invalidReq, endpointHandler);
        Console.WriteLine($"Invalid Req -> Status: {resp1.StatusCode}, Content: {resp1.Content}");

        var validReq = new HttpRequest("POST", "/api/orders", "Item: Laptop Gaming");
        var resp2 = await filter.InvokeAsync(validReq, endpointHandler);
        Console.WriteLine($"Valid Req -> Status: {resp2.StatusCode}, Content: {resp2.Content}");
    }
}
